"""Config-line parser: 'a=1; debug; msg="hi; there"' -> dict."""

def hole_split_fields(line: str) -> list[str]:
    """Split a config line into raw field strings.

    Must split on ';' only when the ';' is outside a double-quoted region.
    Each returned field must be stripped of leading and trailing whitespace.
    Empty fields (e.g. from trailing ';' or consecutive ';;') must be omitted.
    Quote characters must be preserved in the returned strings so that
    later stages can distinguish quoted values.
    Must not raise for unterminated quotes; the remainder of the line is
    treated as part of the current field.
    """
    raise NotImplementedError

def hole_parse_field(field: str) -> tuple[str, object]:
    """Convert one non-empty raw field into a (key, value) pair.

    Rules:
      - 'key'            -> (key, True)        bare key with no '='
      - 'key=value'      -> (key, value)       split on the first '=' only
      - 'key="..."'      -> (key, inner)       surrounding double quotes removed;
                                               inner text kept verbatim
                                               (semicolons and '=' allowed)
      - Whitespace around key and unquoted value must be stripped.
      - An unquoted value is returned as a str, not converted to int/float/bool.
    Must return a tuple whose first element is a non-empty key string.
    Raises ValueError if the key is empty (e.g. '=5' or '"x"').
    """
    raise NotImplementedError

def parse_kv(line: str) -> dict:
    """Parse a config line into a dict.

    Bare keys map to True; quoted values may contain semicolons.
    Later duplicate keys overwrite earlier ones.
    """
    if not isinstance(line, str):
        raise TypeError('line must be a str')
    result: dict = {}
    for field in hole_split_fields(line):
        key, value = hole_parse_field(field)
        result[key] = value
    return result

def check_invariants() -> None:
    assert parse_kv('') == {}
    assert parse_kv('debug') == {'debug': True}
    assert parse_kv('a=1; debug') == {'a': '1', 'debug': True}
    assert parse_kv('msg="hi; there"') == {'msg': 'hi; there'}
    assert parse_kv('a=1; debug; msg="hi; there"') == {'a': '1', 'debug': True, 'msg': 'hi; there'}
    assert parse_kv('a=1; a=2') == {'a': '2'}
    assert parse_kv('x=a=b') == {'x': 'a=b'}
    assert parse_kv('a=1;;  ; b=2 ;') == {'a': '1', 'b': '2'}


