import csv
import io

def hole_parse_cell(cell: str):
    """Convert a single non-empty CSV cell into a number.

    Must return a float (or int) parsed from the string `cell`, which is
    guaranteed by the caller to be non-empty after stripping whitespace.
    Must raise ValueError if the cell is not a valid number.
    Leading/trailing whitespace in `cell` should be ignored.
    """
    raise NotImplementedError

def hole_is_skippable(cell: str) -> bool:
    """Decide whether a raw CSV cell should be excluded from statistics.

    Must return True if the cell should be skipped (e.g. empty or only
    whitespace), and False if it should be parsed and included.
    """
    raise NotImplementedError

def hole_combine_stats(count: int, total, minimum, maximum, value):
    """Fold one new numeric value into the running statistics.

    Must return a tuple (count, total, minimum, maximum) updated to include
    `value`. `count` is the number of values seen so far (0 initially),
    `total` the running sum, and `minimum`/`maximum` the running extremes
    (None when count is 0). The returned tuple must reflect `value` added.
    """
    raise NotImplementedError

def column_stats(csv_text: str, column: str) -> dict:
    """Return count, sum, mean, min and max of a numeric column.

    `csv_text` is CSV text with a header row. `column` is the header name
    of the column to analyse. Empty cells are skipped. Returns a dict with
    keys "count", "sum", "mean", "min", "max". If no numeric values are
    present, count is 0 and sum, mean, min and max are None.
    Raises KeyError if the column is not present in the header.
    """
    reader = csv.DictReader(io.StringIO(csv_text))
    if reader.fieldnames is None or column not in reader.fieldnames:
        raise KeyError(column)
    count = 0
    total = 0
    minimum = None
    maximum = None
    for row in reader:
        raw = row.get(column)
        if raw is None or hole_is_skippable(raw):
            continue
        value = hole_parse_cell(raw)
        count, total, minimum, maximum = hole_combine_stats(count, total, minimum, maximum, value)
    mean = total / count if count else None
    return {'count': count, 'sum': total if count else None, 'mean': mean, 'min': minimum, 'max': maximum}

