import sys

def hole_c_div(a: int, b: int) -> int:
    """Return a / b as an int, truncated toward zero (C semantics).

    Must satisfy: result == -(-a // b) when a and b have opposite signs,
    and result == a // b when they have the same sign.
    Must raise ZeroDivisionError if b == 0.
    """
    raise NotImplementedError

def hole_c_mod(a: int, b: int) -> int:
    """Return the remainder of a divided by b with C semantics.

    The result has the sign of a (or is 0), and must satisfy
    a == b * hole_c_div(a, b) + hole_c_mod(a, b).
    Must raise ZeroDivisionError if b == 0.
    """
    raise NotImplementedError

def hole_pow(base: int, exponent: int) -> int:
    """Return base raised to exponent as an int.

    Must return exactly base ** exponent for exponent >= 0.
    Must raise ValueError if exponent < 0, since the integer result
    is not defined.
    """
    raise NotImplementedError

def _tokenize(expr: str) -> list:
    """Split expr into (kind, value) tokens, ending with an ('END', None) token."""
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif '0' <= ch <= '9':
            j = i
            while j < n and '0' <= expr[j] <= '9':
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
        elif ch in '+-*/%^()':
            tokens.append((ch, ch))
            i += 1
        else:
            raise SyntaxError(f'unexpected character {ch!r} at position {i}')
    tokens.append(('END', None))
    return tokens

class _Parser:

    def __init__(self, tokens: list):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> str:
        return self.tokens[self.pos][0]

    def advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, kind: str):
        if self.peek() != kind:
            raise SyntaxError(f'expected {kind!r}, found {self.peek()!r}')
        return self.advance()

    def parse(self) -> int:
        value = self.parse_expr()
        self.expect('END')
        return value

    def parse_expr(self) -> int:
        value = self.parse_term()
        while self.peek() in ('+', '-'):
            op = self.advance()[0]
            rhs = self.parse_term()
            value = value + rhs if op == '+' else value - rhs
        return value

    def parse_term(self) -> int:
        value = self.parse_unary()
        while self.peek() in ('*', '/', '%'):
            op = self.advance()[0]
            rhs = self.parse_unary()
            if op == '*':
                value = value * rhs
            elif op == '/':
                value = hole_c_div(value, rhs)
            else:
                value = hole_c_mod(value, rhs)
        return value

    def parse_unary(self) -> int:
        if self.peek() == '-':
            self.advance()
            return -self.parse_unary()
        return self.parse_power()

    def parse_power(self) -> int:
        base = self.parse_primary()
        if self.peek() == '^':
            self.advance()
            exponent = self.parse_unary()
            return hole_pow(base, exponent)
        return base

    def parse_primary(self) -> int:
        kind, value = self.tokens[self.pos]
        if kind == 'NUM':
            self.advance()
            return value
        if kind == '(':
            self.advance()
            value = self.parse_expr()
            self.expect(')')
            return value
        raise SyntaxError(f'unexpected token {kind!r} at token index {self.pos}')

def evaluate(expr: str) -> int:
    """Evaluate an integer arithmetic expression and return the int result.

    Supports + - * / % ^, unary minus, and parentheses.
    Raises SyntaxError for malformed input.
    """
    if not isinstance(expr, str):
        raise TypeError('expr must be a str')
    tokens = _tokenize(expr)
    return _Parser(tokens).parse()

def _main() -> int:
    status = 0
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            print(evaluate(line))
        except SyntaxError as exc:
            print(f'syntax error: {exc}', file=sys.stderr)
            status = 1
    return status

def _raises_syntax(expr: str) -> bool:
    try:
        evaluate(expr)
    except SyntaxError:
        return True
    return False

def check_invariants() -> None:
    assert evaluate('1 + 2 * 3') == 7
    assert evaluate('(1 + 2) * 3') == 9
    assert evaluate('-2 ^ 2') == -4
    assert evaluate('2 ^ 3 ^ 2') == 512
    assert evaluate('-7 / 2') == -3
    assert evaluate('-7 % 3') == -1
    assert _raises_syntax('1 +') and _raises_syntax('(1')
if __name__ == '__main__':
    sys.exit(_main())


