import sys
_DIGITS = '0123456789'
_BINARY_OPS = {'+', '-', '*', '/', '%', '^'}

def hole_precedence(op: str) -> tuple[int, bool]:
    """Return (binding_power, is_right_associative) for an operator.

    `op` is one of "+", "-", "*", "/", "%", "^", or "neg" (unary minus).
    Binding powers must be integers >= 1 and must satisfy:
      - "+" and "-" share the same binding power, which is the lowest.
      - "*", "/", "%" share a binding power, higher than "+"/"-".
      - "neg" is strictly higher than "*", "/", "%" and strictly lower than "^",
        so that -2^2 parses as -(2^2).
      - "^" has the highest binding power and is right-associative (True).
      - All other operators are left-associative (False).
    """
    raise NotImplementedError

def hole_divide(a: int, b: int) -> int:
    """Return the integer quotient of a / b, truncated toward zero.

    Must match C semantics: 7 / -2 == -3, -7 / 2 == -3.
    Must raise ZeroDivisionError when b == 0.
    """
    raise NotImplementedError

def hole_modulo(a: int, b: int) -> int:
    """Return the remainder of a % b with C semantics.

    The result takes the sign of the dividend and satisfies
    a == b * hole_divide(a, b) + hole_modulo(a, b).
    Examples: -7 % 3 == -1, 7 % -3 == 1.
    Must raise ZeroDivisionError when b == 0.
    """
    raise NotImplementedError

def hole_power(base: int, exp: int) -> int:
    """Return base raised to exp as an integer.

    Must return 1 for 0 ^ 0. For exp >= 0 returns the exact integer power.
    For exp < 0 must raise ValueError (no rational results).
    """
    raise NotImplementedError

def _tokenize(expr: str) -> list:
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif ch in _DIGITS:
            j = i
            while j < n and expr[j] in _DIGITS:
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
        elif ch in _BINARY_OPS or ch in '()':
            tokens.append((ch, ch))
            i += 1
        else:
            raise SyntaxError(f'unexpected character {ch!r} at position {i}')
    tokens.append(('END', None))
    return tokens

def _apply(op: str, a: int, b: int) -> int:
    if op == '+':
        return a + b
    if op == '-':
        return a - b
    if op == '*':
        return a * b
    if op == '/':
        return hole_divide(a, b)
    if op == '%':
        return hole_modulo(a, b)
    if op == '^':
        return hole_power(a, b)
    raise SyntaxError(f'unknown operator {op!r}')

class _Parser:

    def __init__(self, tokens: list):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> str:
        return self.tokens[self.pos][0]

    def advance(self) -> tuple:
