            if op not in _BINARY_OPS:
                break
            prec, right_assoc = hole_precedence(op)
            if prec < min_bp:
                break
            self.advance()
            next_min = prec if right_assoc else prec + 1
            right = self.parse_expr(next_min)
            left = _apply(op, left, right)
        return left

    def parse_unary(self) -> int:
        if self.peek() == '-':
            self.advance()
            neg_bp, _ = hole_precedence('neg')
            return -self.parse_expr(neg_bp)
        return self.parse_primary()

