    y_num = all((c in digits for c in y))
    if x_num and y_num:
        nx, ny = (int(x), int(y))
        return (nx > ny) - (nx < ny)
    if x_num != y_num:
        return -1 if x_num else 1
    return (x > y) - (x < y)

def hole_compare_prerelease(pa: tuple[str, ...], pb: tuple[str, ...]) -> int:
    if not pa and (not pb):
        return 0
    if not pa:
        return 1
    if not pb:
        return -1
    for x, y in zip(pa, pb):
        c = hole_compare_identifiers(x, y)
        if c != 0:
            return c
    return (len(pa) > len(pb)) - (len(pa) < len(pb))

