"""Skeleton: parse config lines like 'a=1; debug; msg="hi; there"' into a dict.

Public API:
    parse_kv(line: str) -> dict[str, str | bool]

The core parsing policy is delegated to the hole_* helpers below.
"""
from __future__ import annotations

def hole_split_fields(line: str) -> list[str]:
    """Split a config line into raw field strings at top-level semicolons.

    Must return a list of raw field strings (not yet stripped of whitespace
    or interpreted) such that:
      - semicolons that appear inside a double-quoted region are NOT split points;
      - each returned string is exactly the characters between two consecutive
        split points (whitespace is preserved; trimming is done by the caller);
      - empty input or a line ending in a split point yields a trailing or
        single empty string, consistent with a plain split on unquoted ';'.
    """
    raise NotImplementedError

def hole_parse_field(field: str) -> tuple[str, str | bool]:
    """Interpret one stripped, non-empty raw field as a (key, value) pair.

    Must return a 2-tuple (key, value) where:
      - a bare key with no '=' (e.g. 'debug') returns (key, True);
      - 'key=value' returns (key, value) with the key and value both stripped
        of surrounding whitespace;
      - if the value is wrapped in double quotes (e.g. '"hi; there"'), the
        surrounding quotes are removed and the inner text is returned verbatim
        (including any semicolons and whitespace inside the quotes);
      - only the first '=' separates key from value; later '=' characters
        belong to the value.
    """
    raise NotImplementedError

def parse_kv(line: str) -> dict[str, str | bool]:
    """Parse a config line into a dictionary of settings.

    Bare keys map to True; key=value pairs map to their string value;
    quoted values may contain semicolons. Empty fields (e.g. from a
    trailing ';' or a blank line) are ignored.
    """
    result: dict[str, str | bool] = {}
    for raw in hole_split_fields(line):
        field = raw.strip()
        if not field:
            continue
        key, value = hole_parse_field(field)
        result[key] = value
    return result

def check_invariants() -> None:
    assert parse_kv('a=1; debug; msg="hi; there"') == {'a': '1', 'debug': True, 'msg': 'hi; there'}
    assert parse_kv('') == {}
    assert parse_kv('   ') == {}
    assert parse_kv('flag') == {'flag': True}
    assert parse_kv('a=1;') == {'a': '1'}
    assert parse_kv('x="a=b; c"') == {'x': 'a=b; c'}
    assert parse_kv('k=v=w') == {'k': 'v=w'}
    assert parse_kv('s=""') == {'s': ''}


